fn assert_readback_verified(
    journal: &FjallJournal,
    artifact: &AcceptedArtifact,
    policy: RuntimePolicy,
) -> Result<(), String> {
    let record = journal
        .compiled_ir(artifact.digest)
        .map_err(|e| format!("compiled_ir read: {e}"))?
