    let counter = journal
        .artifact_acceptance
        .get(b"last_issued")
        .map_err(|e| format!("read counter: {e}"))?
        .ok_or_else(|| "counter should still exist")?;
    assert_eq!(
        counter,
        &[0, 0, 0, 0, 0, 0, 0, 0, 0],
        "counter should be unchanged"
    );
    assert!(
        journal.compiled_ir.iter().next().is_none(),
        "no compiled_ir written"
